const DICTS: Record<Locale, Dict> = { ru, en, az, ge, it, sp };
const STORAGE_KEY = 'otto-locale';

export function getLocale(): Locale {
  if (typeof window === 'undefined') return 'ru';
  try {
    const saved = window.localStorage.getItem(STORAGE_KEY) as Locale | null;
    if (saved && DICTS[saved]) return saved;
  } catch { /* ignore */ }
  return 'ru';
}

type Vars = Record<string, string | number>;

/** Translate; `{name}` placeholders are filled from `vars`. */
function translate(dict: Dict, key: string, vars?: Vars): string {
  const raw = dict[key] ?? en[key] ?? key;
  return vars ? raw.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : raw;
}

/** Translate outside React (API error messages) in the saved UI language. */
export function tt(key: string, vars?: Vars): string {
  return translate(DICTS[getLocale()], key, vars);
}

interface I18nValue { locale: Locale; setLocale: (l: Locale) => void; t: (key: string, vars?: Vars) => string }
const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>('ru');
  useEffect(() => { setLocaleState(getLocale()); }, []);

  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l);
    try { window.localStorage.setItem(STORAGE_KEY, l); } catch { /* ignore */ }
  }, []);

  const t = useCallback((key: string, vars?: Vars) => translate(DICTS[locale], key, vars), [locale]);

  return <I18nContext.Provider value={{ locale, setLocale, t }}>{children}</I18nContext.Provider>;
}

export function useT(): I18nValue {
  const ctx = useContext(I18nContext);
  if (ctx) return ctx;
  // Fallback outside provider (e.g. SSR) — Russian default, no reactivity.
  return { locale: 'ru', setLocale: () => {}, t: (key: string, vars?: Vars) => translate(DICTS.ru, key, vars) };
}
